const job = $json.body?.job || $json.job || $json;
const clean = (v, max=2500) => String(v ?? "").trim().slice(0,max);
const list = (v) => Array.isArray(v) ? v.map(x=>clean(x,500)).filter(Boolean) : [];
return [{
  json:{
    jobId: clean(job.jobId || $json.body?.jobId,160),
    callbackUrl: clean(job.callbackUrl || $json.callbackUrl,1000),
    callbackSecret: clean($env.MERQIVA_RESEARCH_CALLBACK_SECRET,500),
    productName: clean(job.productName,240),
    productId: clean(job.productId,160),
    targetMarket: clean(job.targetMarket,500),
    researchQuestion: clean(job.researchQuestion,2500),
    targetCompanyTypes: list(job.targetCompanyTypes),
    targetVesselTypes: list(job.targetVesselTypes),
    relevantSignals: list(job.relevantSignals),
    targetDecisionMakerRoles: list(job.targetDecisionMakerRoles),
    maxOpportunities: Math.max(1, Math.min(10, Number(job.maxOpportunities)||10)),
    language: ["en","ar"].includes(job.language) ? job.language : "en"
  }
}];

const raw = String($json.data || $json.body || $json || "");
const items = [];
const re = /<item>([\\s\\S]*?)<\\/item>/gi;
let m;
while ((m = re.exec(raw)) && items.length < 30) {
  const block=m[1];
  const get=(tag)=>{ const x=new RegExp('<'+tag+'[^>]*>([\\s\\S]*?)<\\/'+tag+'>','i').exec(block); return x ? x[1].replace(/<!\\[CDATA\\[|\\]\\]>/g,'').trim() : ''; };
  items.push({title:get('title'),link:get('link'),pubDate:get('pubDate'),description:get('description')});
}
return [{json:{newsItems:items}}];

