const job = $node["Normalize Research Job"].json;
const response = $json;
let raw = response?.choices?.[0]?.message?.content ?? response?.output ?? response?.text ?? response;
if (typeof raw !== "string") raw = JSON.stringify(raw);
raw = raw.trim().replace(/^\`\`\`json/i, "").replace(/^\`\`\`/i, "").replace(/\`\`\`$/i, "").trim();
let result;
try { result = JSON.parse(raw); } catch (error) { throw new Error("LLM did not return valid JSON: " + error.message); }

const opportunities = Array.isArray(result.opportunities)
  ? result.opportunities.slice(0, job.maxOpportunities)
  : [];

for (const op of opportunities) {
  if (!op.companyName || !op.productName) continue;
  if (!Array.isArray(op.evidence)) op.evidence = [];
  op.buyingSignals = Array.isArray(op.buyingSignals) ? op.buyingSignals : [];
  op.status = "New";
}

return [{json:{
  jobId: job.jobId,
  callbackUrl: job.callbackUrl,
  callbackSecret: job.callbackSecret,
  provider: "N8N",
  status: result.status === "FAILED" ? "FAILED" : "COMPLETED",
  notes: String(result.notes || "").slice(0,2500),
  opportunities
}}];
